INSERT INTO consultation_records (consultation_record_id, patient_id, service_id, queue_id, bill_id, status, is_paid, requested_by, consulted_by, consultation_type, diagnosis, presenting_complaint, vital_signs, physical_examination, notes, requested_at, consulted_at) VALUES
  ('CR-26-1005-0001', 'P-26-1003-0001', 'S-26-10-001', 'CONS-0001', 'B-26-1005-0001', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0002', 'Initial', '[{"diagnosis": "Acute pharyngitis, unspecified", "icd10": "J02.9", "type": "Primary"}]'::jsonb, '{"hpi": "3 days of sore throat and painful swallowing with low-grade fever. No cough or difficulty of breathing."}'::jsonb, '{"blood_pressure": "110/70 mmHg", "heart_rate": "82 bpm", "respiratory_rate": "18 cpm", "temperature": "37.8 °C", "weight": "54 kg", "height": "158 cm", "oxygen_saturation": "99%"}'::jsonb, '{"general_appearance": "Awake, ambulatory, mildly distressed from throat pain.", "heent": "Pharyngeal erythema, tonsils grade 1 without exudates. No cervical lymphadenopathy.", "respiratory": "Clear breath sounds, no wheezes or crackles."}'::jsonb, 'Advised rest, increased oral fluids, and warm saline gargles. Return if fever persists beyond 3 days.', '2026-10-05 01:05:00', '2026-10-05 01:10:00'),
  ('CR-26-1005-0002', 'P-26-1003-0002', 'S-26-10-001', 'CONS-0002', 'B-26-1005-0002', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0002', 'Initial', '[{"diagnosis": "Essential (primary) hypertension", "icd10": "I10", "type": "Primary"}]'::jsonb, '{"hpi": "Recurrent morning headaches and occasional dizziness for 2 weeks. Home BP readings 150-160/90-100."}'::jsonb, '{"blood_pressure": "158/98 mmHg", "heart_rate": "88 bpm", "respiratory_rate": "18 cpm", "temperature": "36.6 °C", "weight": "82 kg", "height": "170 cm", "oxygen_saturation": "98%"}'::jsonb, '{"general_appearance": "Well-nourished, no acute distress.", "cardiovascular": "Regular rate and rhythm, no murmurs.", "extremities": "No edema, full pulses."}'::jsonb, 'Start antihypertensive. Low-salt diet counselling given. Monitor BP daily; follow up in 1 week.', '2026-10-05 02:20:00', '2026-10-05 02:25:00'),
  ('CR-26-1007-0001', 'P-26-1005-0002', 'S-26-10-001', 'CONS-0003', 'B-26-1007-0001', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0003', 'Initial', '[{"diagnosis": "Type 2 diabetes mellitus without complications", "icd10": "E11.9", "type": "Primary"}, {"diagnosis": "Essential (primary) hypertension", "icd10": "I10", "type": "Secondary"}]'::jsonb, '{"hpi": "Increased thirst, frequent urination and fatigue for 1 month. Known hypertensive, irregular maintenance meds."}'::jsonb, '{"blood_pressure": "148/92 mmHg", "heart_rate": "80 bpm", "respiratory_rate": "18 cpm", "temperature": "36.5 °C", "weight": "78 kg", "height": "165 cm", "oxygen_saturation": "97%"}'::jsonb, '{"general_appearance": "Elderly male, fatigued but conversant.", "cardiovascular": "Regular rhythm, no murmurs.", "abdomen": "Soft, non-tender, no organomegaly.", "extremities": "No pedal edema; intact foot sensation."}'::jsonb, 'Fasting blood sugar and lipid profile requested. Start metformin and resume losartan.', '2026-10-07 01:35:00', '2026-10-07 01:40:00'),
  ('CR-26-1009-0001', 'P-26-1005-0001', 'S-26-10-001', 'CONS-0004', 'B-26-1009-0001', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0003', 'Initial', '[{"diagnosis": "Acute upper respiratory infection, unspecified", "icd10": "J06.9", "type": "Primary"}]'::jsonb, '{"hpi": "Cough with colds and nasal congestion for 4 days, intermittent fever, body malaise."}'::jsonb, '{"blood_pressure": "100/70 mmHg", "heart_rate": "90 bpm", "respiratory_rate": "20 cpm", "temperature": "38.1 °C", "weight": "50 kg", "height": "155 cm", "oxygen_saturation": "98%"}'::jsonb, '{"general_appearance": "Alert, febrile.", "heent": "Congested nasal mucosa with clear discharge; throat mildly erythematous.", "respiratory": "Clear breath sounds."}'::jsonb, 'CBC and urinalysis requested to rule out bacterial infection.', '2026-10-09 06:00:00', '2026-10-09 06:05:00'),
  ('CR-26-1012-0001', 'P-26-1003-0002', 'S-26-10-002', 'CONS-0005', 'B-26-1012-0001', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0002', 'Follow-up', '[{"diagnosis": "Essential (primary) hypertension", "icd10": "I10", "type": "Primary"}]'::jsonb, '{"hpi": "Follow-up for hypertension. Headaches improved; BP still above target on 5 mg amlodipine."}'::jsonb, '{"blood_pressure": "142/90 mmHg", "heart_rate": "78 bpm", "respiratory_rate": "17 cpm", "temperature": "36.6 °C", "weight": "81 kg", "height": "170 cm", "oxygen_saturation": "98%"}'::jsonb, '{"general_appearance": "Well appearing.", "cardiovascular": "Regular rate and rhythm."}'::jsonb, 'Increase amlodipine to 10 mg once daily. Continue diet modification.', '2026-10-12 02:55:00', '2026-10-12 03:00:00'),
  ('CR-26-1014-0001', 'P-26-1012-0001', 'S-26-10-001', 'CONS-0006', 'B-26-1014-0001', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0002', 'Initial', '[{"diagnosis": "Osteoarthritis of knee, unspecified", "icd10": "M17.9", "type": "Primary"}]'::jsonb, '{"hpi": "Bilateral knee pain worse on climbing stairs and in the morning, lasting less than 30 minutes."}'::jsonb, '{"blood_pressure": "130/80 mmHg", "heart_rate": "74 bpm", "respiratory_rate": "18 cpm", "temperature": "36.4 °C", "weight": "60 kg", "height": "150 cm", "oxygen_saturation": "97%"}'::jsonb, '{"general_appearance": "Elderly female, ambulates with mild antalgic gait.", "extremities": "Bilateral knee crepitus, mild joint-line tenderness, no effusion."}'::jsonb, 'Chest X-ray requested as pre-medication screening. Start celecoxib short course.', '2026-10-14 00:45:00', '2026-10-14 00:50:00'),
  ('CR-26-1017-0001', 'P-26-1008-0002', 'S-26-10-001', 'CONS-0007', 'B-26-1017-0003', 'Completed', TRUE, 'U-26-1001-0004', 'U-26-1001-0002', 'Initial', '[{"diagnosis": "Gastro-esophageal reflux disease without esophagitis", "icd10": "K21.9", "type": "Primary"}]'::jsonb, '{"hpi": "Burning epigastric pain and sour taste after meals for 3 weeks, worse when lying down."}'::jsonb, '{"blood_pressure": "126/82 mmHg", "heart_rate": "76 bpm", "respiratory_rate": "18 cpm", "temperature": "36.7 °C", "weight": "88 kg", "height": "172 cm", "oxygen_saturation": "99%"}'::jsonb, '{"general_appearance": "Overweight, comfortable.", "abdomen": "Mild epigastric tenderness, no guarding or rebound."}'::jsonb, 'Lifestyle modification and PPI trial. Fasting blood sugar requested.', (CURRENT_DATE + INTERVAL '5 minutes'), (CURRENT_DATE + INTERVAL '10 minutes')),
  ('CR-26-1017-0002', 'P-26-1003-0002', 'S-26-10-002', 'CONS-0008', 'B-26-1017-0001', 'In Queue', TRUE, 'U-26-1001-0004', NULL, 'Follow-up', NULL, NULL, NULL, NULL, NULL, (CURRENT_DATE + INTERVAL '12 minutes'), NULL),
  ('CR-26-1017-0003', 'P-26-1005-0002', 'S-26-10-001', 'CONS-0009', 'B-26-1017-0004', 'In Queue', TRUE, 'U-26-1001-0004', NULL, 'Follow-up', NULL, NULL, NULL, NULL, NULL, (CURRENT_DATE + INTERVAL '20 minutes'), NULL),
  ('CR-26-1017-0004', 'P-26-1008-0001', 'S-26-10-001', 'CONS-0010', 'B-26-1017-0005', 'In Queue', TRUE, 'U-26-1001-0004', NULL, 'Initial', NULL, NULL, NULL, NULL, NULL, (CURRENT_DATE + INTERVAL '28 minutes'), NULL),
