-- =============================================================================
-- TechCare seed data. Every row has the shape the application itself writes, so
-- each screen shows it exactly as it would after going through the frontend.
--
-- Fresh start: drop the database, then run  npm run seed  (it creates the tables).
-- Safe to re-run: every INSERT skips rows that already exist.
-- Rows for "today" are stamped from CURRENT_DATE because the queue screens only
-- show today's rows. Reseed on another day to get a fresh queue.
-- Images are public randomuser.me and picsum.photos URLs, not Cloudinary.
--
-- LOGIN  (every password is: password)
--   admin101      admin             U-26-1001-0001
--   doctor201     doctor            U-26-1001-0002   Ramon Aguilar
--   doctor202     doctor            U-26-1001-0003   Cecilia Torres
--   fdstaff322    frontdesk-staff   U-26-1001-0004
--   fdstaff323    frontdesk-staff   U-26-1001-0005
--   labstaff101   laboratory-staff  U-26-1001-0007   Laboratory Room 1
--   labstaff202   laboratory-staff  U-26-1001-0006   Laboratory Room 2
--   fdstaff324    frontdesk-staff   U-26-1001-0008   deactivated, login returns 403
--   patient101 .. patient108        patients
--
-- BILLING ON THE FRONT DESK SCREEN
--   Pending: B-26-1017-0002 (Patricia), B-26-1017-0009 (Teresita, senior discount)
--   Paid, tests still need forwarding: B-26-1017-0008 (Teresita)
--   PWD discount: B-26-1017-0003 (Carlos)
-- =============================================================================

BEGIN;


-- users  (every password is: password)
ON CONFLICT DO NOTHING;

-- patients  (same fields as the registration form)
ON CONFLICT DO NOTHING;

-- services
ON CONFLICT DO NOTHING;

-- actions
ON CONFLICT DO NOTHING;

-- queue_entries  (consultation numbers are per day; laboratory numbers are per room per day)
ON CONFLICT DO NOTHING;

-- bills  (paid bills keep the itemized prices that were charged; open bills follow their linked rows)
ON CONFLICT DO NOTHING;

-- consultation_records  (findings are only filled in once the visit is completed)
ON CONFLICT DO NOTHING;

-- prescription_records  (prescription_items = [{medication, dosage, frequency, duration, instructions}])
ON CONFLICT DO NOTHING;

-- laboratory_requests
ON CONFLICT DO NOTHING;

-- laboratory_request_items  (every item is linked to a bill; a queue entry exists only after payment)
ON CONFLICT DO NOTHING;

-- form_component_types  (identical to registerFormComponentTypes())
ON CONFLICT DO NOTHING;

-- form_templates  (one Published template per lab service)
ON CONFLICT DO NOTHING;

-- form_components
ON CONFLICT DO NOTHING;

-- laboratory_results  (results[0].template_snapshot is required by the lab/doctor report views; 'Released' rows are what patients/doctors see, 'Pending' is a saved-but-unreleased draft)
ON CONFLICT DO NOTHING;

-- system_activity  (legacy audit table)
ON CONFLICT DO NOTHING;

-- activity_logs  (metadata is an object, exactly as activityLogger.ts writes it; re-run safe via NOT EXISTS)
SELECT v.user_id, v.action_id, v.status, v.target_type, v.target_id, v.metadata, v.created_at
FROM (VALUES
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.create'), 'success', 'user', 'U-26-1001-0002', '{"role": "doctor", "department": "Internal Medicine"}'::jsonb, '2026-10-01 01:00:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.create'), 'success', 'user', 'U-26-1001-0004', '{"role": "frontdesk-staff"}'::jsonb, '2026-10-01 01:00:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.create'), 'success', 'user', 'U-26-1001-0006', '{"role": "laboratory-staff"}'::jsonb, '2026-10-01 01:05:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'service.create'), 'success', 'service', 'S-26-10-001', '{"service_name": "General Consultation", "price": 500}'::jsonb, '2026-10-01 01:30:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'form_template.create'), 'success', 'form_template', 'F-1790906400000', '{"form_name": "Complete Blood Count", "status": "Published"}'::jsonb, '2026-10-02 02:00:00'),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'patient.register'), 'success', 'patient', 'P-26-1003-0001', '{"first_name": "Maria", "last_name": "Santos"}'::jsonb, '2026-10-03 02:00:00'),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'patient.register'), 'success', 'patient', 'P-26-1003-0002', '{"first_name": "Juan", "last_name": "Dela Cruz"}'::jsonb, '2026-10-03 02:20:00'),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'queue.add'), 'success', 'queue_entry', 'CONS-0001', '{"queue_number": 1, "is_priority": false}'::jsonb, '2026-10-05 01:05:00'),
  ('U-26-1001-0002', (SELECT action_id FROM actions WHERE action_name = 'consultation.create'), 'success', 'consultation_record', 'CR-26-1005-0001', '{"patient_id": "P-26-1003-0001", "diagnosis": "J02.9"}'::jsonb, '2026-10-05 01:30:00'),
  ('U-26-1001-0002', (SELECT action_id FROM actions WHERE action_name = 'prescription.create'), 'success', 'prescription_record', 'RX-26-1005-0001', '{"items": 2}'::jsonb, '2026-10-05 01:40:00'),
  ('U-26-1001-0003', (SELECT action_id FROM actions WHERE action_name = 'laboratory.request'), 'success', 'laboratory_request', 'LR-26-1007-0001', '{"patient_id": "P-26-1005-0002", "tests": 2, "priority": true}'::jsonb, '2026-10-07 02:00:00'),
  ('U-26-1001-0006', (SELECT action_id FROM actions WHERE action_name = 'laboratory.result.save'), 'success', 'laboratory_result', 'LI-26-1007-0001', '{"service": "Fasting Blood Sugar (FBS)"}'::jsonb, '2026-10-07 05:30:00'),
  ('U-26-1001-0006', (SELECT action_id FROM actions WHERE action_name = 'laboratory.result.release'), 'success', 'laboratory_result', 'LI-26-1007-0001', '{"service": "Fasting Blood Sugar (FBS)"}'::jsonb, '2026-10-07 06:00:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'service.update'), 'success', 'service', 'S-26-10-009', '{"field": "price", "old": 600, "new": 650}'::jsonb, '2026-10-05 03:00:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.deactivate'), 'success', 'user', 'U-26-1001-0008', '{"newStatus": "deactivated"}'::jsonb, '2026-10-10 07:00:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.deactivate'), 'blocked', 'user', 'U-26-1001-0001', '{"reason": "self-deactivation attempt"}'::jsonb, '2026-10-10 07:05:00'),
  ('U-26-1001-0008', (SELECT action_id FROM actions WHERE action_name = 'user.login'), 'failure', 'user', 'U-26-1001-0008', '{"reason": "account deactivated"}'::jsonb, '2026-10-10 23:02:00'),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'patient.update'), 'success', 'patient', 'P-26-1012-0001', '{"fields": ["address", "contact_number"]}'::jsonb, '2026-10-12 02:30:00'),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'patient.delete'), 'failure', 'patient', 'P-26-9999-0001', '{"reason": "patient not found"}'::jsonb, '2026-10-13 05:15:00'),
  ('U-26-1001-0001', (SELECT action_id FROM actions WHERE action_name = 'user.login'), 'success', 'user', 'U-26-1001-0001', '{"ip": "203.0.113.10"}'::jsonb, (CURRENT_DATE + INTERVAL '3 minutes')),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'user.login'), 'success', 'user', 'U-26-1001-0004', '{"ip": "203.0.113.21"}'::jsonb, (CURRENT_DATE + INTERVAL '4 minutes')),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'queue.add'), 'success', 'queue_entry', 'CONS-0007', '{"queue_number": 1, "is_priority": false}'::jsonb, (CURRENT_DATE + INTERVAL '5 minutes')),
  ('U-26-1001-0004', (SELECT action_id FROM actions WHERE action_name = 'queue.add'), 'success', 'queue_entry', 'CONS-0009', '{"queue_number": 3, "is_priority": true}'::jsonb, (CURRENT_DATE + INTERVAL '20 minutes')),
  ('U-26-1001-0002', (SELECT action_id FROM actions WHERE action_name = 'consultation.create'), 'success', 'consultation_record', 'CR-26-1017-0001', '{"patient_id": "P-26-1008-0002", "diagnosis": "K21.9"}'::jsonb, (CURRENT_DATE + INTERVAL '10 minutes')),
  ('U-26-1001-0002', (SELECT action_id FROM actions WHERE action_name = 'prescription.create'), 'success', 'prescription_record', 'RX-26-1017-0001', '{"items": 1}'::jsonb, (CURRENT_DATE + INTERVAL '12 minutes')),
  ('U-26-1001-0007', (SELECT action_id FROM actions WHERE action_name = 'queue.accept'), 'success', 'queue_entry', 'LAB-0005', '{"room": "Laboratory Room 1"}'::jsonb, (CURRENT_DATE + INTERVAL '38 minutes')),
  ('U-26-1001-0006', (SELECT action_id FROM actions WHERE action_name = 'laboratory.result.save'), 'success', 'laboratory_result', 'LI-26-1017-0001', '{"service": "Fasting Blood Sugar (FBS)"}'::jsonb, (CURRENT_DATE + INTERVAL '36 minutes')),
  ('U-26-1001-0007', (SELECT action_id FROM actions WHERE action_name = 'queue.skip'), 'success', 'queue_entry', 'LAB-0008', '{"queue_number": 2}'::jsonb, (CURRENT_DATE + INTERVAL '46 minutes'))
) AS v(user_id, action_id, status, target_type, target_id, metadata, created_at)
WHERE NOT EXISTS (
  SELECT 1 FROM activity_logs a
  WHERE a.user_id = v.user_id AND a.action_id = v.action_id AND a.status = v.status
    AND a.target_type = v.target_type AND a.target_id = v.target_id
);

COMMIT;
